import {ATTRIBUTES,ITEM_BY_ID,CHAMPIONS} from './gladiator-data.js';
import {skillById} from './math-curriculum.js';
const count=n=>Number.isSafeInteger(n)&&n>=0;
const obj=v=>!!v&&typeof v==='object'&&!Array.isArray(v);
export function validateQuestProgress(p){
 if(p.mathQuest!==undefined){const m=p.mathQuest;if(!obj(m)||m.version!==1||!Number.isInteger(m.grade)||m.grade<0||m.grade>8||!['answered','correct','wrong','bestScore','stars'].every(k=>count(m[k]))||m.correct+m.wrong!==m.answered||typeof m.tutorial!=='boolean'||!obj(m.settings)||!obj(m.skills)||!obj(m.worlds))throw Error('Math Quest progress is invalid.');if(!['Easy','Normal','Hard','Adaptive'].includes(m.settings.difficulty)||!['adventure','practice','mixed','speed','homework'].includes(m.settings.mode)||![5,10,15,20].includes(m.settings.count)||typeof m.settings.timer!=='boolean')throw Error('Math Quest settings are invalid.');for(const [id,s]of Object.entries(m.skills))if(!skillById(id)||!obj(s)||!['attempts','correct','wrong','streak','bestStreak','independent'].every(k=>count(s[k]))||s.attempts!==s.correct+s.wrong||s.independent>s.correct||s.streak>s.bestStreak||!Number.isInteger(s.stage)||s.stage<0||s.stage>2||!['Practicing','Needs practice','Mastered'].includes(s.status))throw Error('A mathematics skill is invalid.');for(const [id,w]of Object.entries(m.worlds))if(!/^[0-8]-[0-5]$/.test(id)||!obj(w)||!count(w.stages)||w.stages>3||!count(w.stars))throw Error('A mathematics world is invalid.');}
 if(p.gladiatorArena!==undefined){const a=p.gladiatorArena;if(!obj(a)||a.version!==1||!Array.isArray(a.characters)||a.characters.length>200||!obj(a.duels)||!['wins','losses','draws'].every(k=>count(a.duels[k])))throw Error('Gladiator careers are invalid.');if(a.audio&&(!obj(a.audio)||!Number.isFinite(a.audio.music)||a.audio.music<0||a.audio.music>.5||!Number.isFinite(a.audio.sfx)||a.audio.sfx<0||a.audio.sfx>1))throw Error('Arena sound settings are invalid.');const ids=new Set();for(const g of a.characters){if(!obj(g)||typeof g.id!=='string'||g.id.length>100||ids.has(g.id)||typeof g.name!=='string'||g.name.length>24||!g.name.trim()||!Number.isInteger(g.level)||g.level<1||g.level>30||!['xp','gold','skillPoints','wins','losses','battles'].every(k=>count(g[k]))||![0,1,2].includes(g.difficulty)||!obj(g.attributes)||!Object.keys(ATTRIBUTES).every(k=>Number.isInteger(g.attributes[k])&&g.attributes[k]>=3&&g.attributes[k]<=65)||!obj(g.appearance)||!/^#[a-f0-9]{6}$/i.test(g.appearance.skin)||!/^#[a-f0-9]{6}$/i.test(g.appearance.hair)||!['bald','short','spikes','long','mohawk'].includes(g.appearance.hairStyle)||!['none','stubble','moustache','full'].includes(g.appearance.beard)||!['brave','angry','silly'].includes(g.appearance.eyes)||!Number.isFinite(g.appearance.body)||g.appearance.body<.85||g.appearance.body>1.21||!Array.isArray(g.inventory)||g.inventory.length>Object.keys(ITEM_BY_ID).length||!g.inventory.every(id=>!!ITEM_BY_ID[id])||!obj(g.equipped)||!Object.entries(g.equipped).every(([slot,id])=>ITEM_BY_ID[id]?.slot===slot&&g.inventory.includes(id))||!Array.isArray(g.champions)||new Set(g.champions).size!==g.champions.length||!g.champions.every(id=>CHAMPIONS.some(c=>c.id===id)))throw Error('A saved gladiator is invalid.');ids.add(g.id);}if(a.selected!==null&&!ids.has(a.selected))throw Error('The selected gladiator is invalid.');}
 return true;
}
